#nullable enable // autogenerated

using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Projectiles;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2Logic.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;
using MVZ2.GameContent.Buffs.Projectiles;
using PVZEngine.Buffs;
namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.quintspenser)]
    public class Quintspenser : DispenserFamily
    {
        public Quintspenser(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            if (!entity.IsEvoked())
            {
                ShootTick(entity);
                return;
            }
        }
        public override void OnShootTick(Entity entity)
        {
            var lane = entity.GetLane();
            var maxLane = entity.Level.GetMaxLaneCount();
            int makeupCount = 0;
            for (int i = lane - 2; i <= lane + 2; i++)
            {
                var bullet = Shoot(entity);
                if (bullet == null)
                    continue;
                if (i < 0 || i >= maxLane)
                {
                    makeupCount++;
                    bullet.Velocity *= 1 + (MAKE_UP_VELOCITY_MULTIPLIER_INCREAMENT * makeupCount);
                }
                else if (i != lane && !bullet.DirectionChangedByKrakensTentacle())
                {
                    bullet.StartChangingLane(i);
                }
            }
        }
        protected override void OnEvoke(Entity entity)
        {
            base.OnEvoke(entity);
            // 选检测范围内血量最高的敌人
            var detector = GetDetector();
            entity.Target = detector.DetectEntityWithTheLeast(entity, t => -t.Health);

            var blueParam = entity.GetShootParams();
            blueParam.damage = entity.GetDamage() * 90;
            blueParam.projectileID = VanillaProjectileID.threeBodyBlue;
            blueParam.velocity = blueParam.velocity.normalized * 2;

            var blue = entity.ShootProjectile(blueParam);
            if (blue == null)
                return;

            if (entity.Target != null)
            {
                var homingBuff = blue.AddBuff<HomingProjectileBuff>();
                if (homingBuff != null)
                {
                    HomingProjectileBuff.SetTarget(homingBuff, new EntityID(entity.Target));
                    HomingProjectileBuff.SetSpeed(homingBuff, blueParam.velocity.magnitude);
                }
            }
        

            var redParam = entity.GetShootParams();
            redParam.damage = entity.GetDamage() * 50;
            redParam.projectileID = VanillaProjectileID.threeBodyRed;
            redParam.velocity = Vector3.zero;
            var red = entity.ShootProjectile(redParam);
            if (red != null)
            {
                red.SetParent(blue);
                HellPlanet.SetOrbitDistance(red, 72);
                HellPlanet.SetOrbitSpeed(red, 4);
            }

            var otherWorldParam = entity.GetShootParams();
            otherWorldParam.damage = entity.GetDamage() * 40;
            otherWorldParam.projectileID = VanillaProjectileID.threeBodyOtherworld;
            otherWorldParam.velocity = Vector3.zero;
            var otherWorld = entity.ShootProjectile(otherWorldParam);
            if (otherWorld != null)
            {
                otherWorld.SetParent(red);
                HellPlanet.SetOrbitDistance(otherWorld, 72);
                HellPlanet.SetOrbitSpeed(otherWorld, 8);
            }

            entity.PlaySound(VanillaSoundID.odd);
            entity.PlaySound(VanillaSoundID.boon);

            var moonParam = entity.GetShootParams();
            moonParam.damage = entity.GetDamage() * 10;
            moonParam.projectileID = VanillaProjectileID.threeBodyMoon;
            moonParam.velocity = Vector3.zero;
            var moon = entity.ShootProjectile(moonParam);
            if (moon != null)
            {
                moon.SetParent(otherWorld);
                HellPlanet.SetOrbitDistance(moon, 72);
                HellPlanet.SetOrbitSpeed(moon, 12);
            }

            var earthParam = entity.GetShootParams();
            earthParam.damage = entity.GetDamage() * 20;
            earthParam.projectileID = VanillaProjectileID.threeBodyEarth;
            earthParam.velocity = Vector3.zero;
            var earth = entity.ShootProjectile(earthParam);
            if (earth != null)
            {
                earth.SetParent(blue);
                HellPlanet.SetOrbitDistance(earth, 144);
                HellPlanet.SetOrbitSpeed(earth, 4);
            }

            var lightParam = entity.GetShootParams();
            lightParam.damage = entity.GetDamage() * 10;
            lightParam.projectileID = VanillaProjectileID.threeBodyLight;
            lightParam.velocity = Vector3.zero;
            var light = entity.ShootProjectile(lightParam);
            if (light != null)
            {
                light.SetParent(earth);
                HellPlanet.SetOrbitDistance(light, 72);
                HellPlanet.SetOrbitSpeed(light, 10);
            }
        }
        protected override Detector GetDetector()
        {
            return new DispenserDetector()
            {
                ignoreHighEnemy = true,
                innerLaneExpansion = 2,
                outerLaneExpansion = 2,
            };
        }
        public const float MAKE_UP_VELOCITY_MULTIPLIER_INCREAMENT = 0.2f;
    }
}
